import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogTitle } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { DialogCloseButton, DialogTitle as DialogTitleRoot } from '@/components/ui/dialog'
import { EmptyState, NoMatchesState, StatsBar } from '@/components/stockpilot/states'
import { useInventory } from '@/lib/inventory/use-inventory'
import { InventoryItem } from '@/lib/inventory/types'
import { ItemForm, ItemTable } from '@/components/stockpilot/item-form'
import { ItemTable as ItemTableRoot, ItemTableProps } from '@/components/stockpilot/item-table'
import { DialogFooter as DialogFooterRoot } from '@/components/ui/dialog'

interface Props {
  items: InventoryItem[]
  initial: InventoryItem | null
  q: string
  category: string
  status: string
}

export function StockPilot({ items, initial, q, category, status }: Props) {
  const [open, setOpen] = useState(false)
  const [editing, setEditing] = useState(initial)
  const [confirmItem, setConfirmItem] = useState(null)
  const [toast, setToast] = useState(null)

  const { data, error, isLoading } = useInventory({ q, category, status })

  return (
    <>
      <Dialog
        open={open}
        onOpenChange={setOpen}
        onClose={() => setOpen(false)}
        title={<DialogTitleRoot className="w-full">StockPilot</DialogTitleRoot>}
      >
        <DialogContent>
          <DialogDescription>{`Find items matching your query '${q}' in category '${category}' and status '${status}'`}</DialogDescription>
          <DialogFooter>
            <DialogFooterRoot>
              <Button onClick={() => setOpen(false)}>Cancel</Button>
              <Button onClick={() => setOpen(false)} type="button" variant="destructive" disabled={isLoading}>
                Delete item
              </Button>
              <Button onClick={() => setOpen(false)} type="button" variant="destructive" disabled={isLoading}>
                Delete all items
              </Button>
            </DialogFooter>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <div className="grid grid-cols-1 gap-4 p-4">
        <div className="h-20 flex justify-center items-center">
          <EmptyState
            className="h-16 w-full"
            text="No items found"
            onRetry={() => setOpen(true)}
            loading={isLoading}
            toast={toast}
          />
        </div>

        <div className="mt-2 flex flex-col justify-center gap-4">
          <Toolbar items={items} />
          <StatsBar items={items} />
          <div className="flex flex-col gap-2">
            <ItemTable
              items={items}
              initial={initial}
              editing={editing}
              onClose={setOpen}
              onSaved={setConfirmItem}
            />
            {editing && (
              <ItemForm
                initial={initial}
                q={q}
                category={category}
                status={status}
                setEditing={setEditing}
                confirmItem={confirmItem}
                onClose={setOpen}
                onSaved={setConfirmItem}
              />
            )}
            {confirmItem && (
              <ConfirmDialog
                toast={toast}
                confirmItem={confirmItem}
                onClose={() => setConfirmItem(null)}
                onRetry={() => setOpen(false)}
              />
            )}
          </div>
        </div>
      </div>
    </>
  )
}

